html:
{%- macro d(value) -%}{%- if value -%}{{ frappe.format_date(value, "dd/MM/yyyy") }}{%- endif -%}{%- endmacro -%}
{%- macro m(value) -%}{{ print_currency(value or 0, currency=doc.get("currency")) }}{%- endmacro -%}
{%- macro item_name(item) -%}{{ item.get("item_code") or "" }}{% if item.get("item_name") and item.get("item_name") != item.get("item_code") %} {{ item.get("item_name") }}{% endif %}{%- endmacro -%}
{%- set sales_people = [] -%}
{%- for st in doc.get("sales_team") or [] -%}{{ sales_people.append(st.get("sales_person")) or "" }}{%- endfor -%}
{%- set items = doc.get("items") or [] -%}
{%- set page_size = 7 -%}
{%- set overflow_size = 20 -%}
{%- set total_pages = ((items|length - page_size) / overflow_size)|round(0, 'ceil')|int + 1 if items|length > page_size else 1 -%}

{%- for page_num in range(total_pages) -%}
{%- if page_num == 0 -%}
  {%- set ns = namespace(start=0, end=page_size) -%}
{%- else -%}
  {%- set ns = namespace(start=page_size + (page_num - 1) * overflow_size, end=page_size + page_num * overflow_size) -%}
{%- endif -%}
<div class="page">
  <div class="f company-address big"> {{ doc.company_address_display }}</div>
  <div class="f company-tax small">{{ doc.get("company_tax_id") or "" }}</div>
  <div class="f party-name nowrap medium">{{ doc.get("customer_name") or doc.get("customer") or "" }}</div>
  <div class="f party-address medium">{{ (doc.get("address_display") or "") }}</div>
  <div class="f party-tax small">{{ doc.get("tax_id") or "" }}</div>
  <div class="f reference small">{{ doc.get("po_no") or "" }}</div>
  <div class="f delivery-by small">{{ doc.get("transporter_name") or doc.get("driver") or "" }}</div>
  <div class="f doc-no">{{ doc.get("name") }}</div>
  <div class="f doc-date">{{ d(doc.get("transaction_date")) }}</div>
  <div class="f delivery-date">{{ d(doc.get("delivery_date")) }}</div>
  <div class="f sales-person small">{{ sales_people|join(", ") }}</div>
  <div class="f territory small">{{ doc.get("territory") or "" }}</div>
  <div class="f items"><table>
    {%- for item in items[ns.start:ns.end] -%}
      <tr>
        <td class="col-no">{{ ns.start + loop.index }}</td>
        <td class="col-desc">{{ item_name(item) }}</td>
        <td class="col-qty">{{ "%g"|format(item.get("qty") or 0) }} {{ item.get("uom") or "" }}</td>
        <td class="col-rate">{{ print_currency(item.get("rate") or 0, currency=doc.get("currency")) }}</td>
        <td class="col-amount">{{ print_currency(item.get("amount") or 0, currency=doc.get("currency")) }}</td>
        <td class="col-wh">{{ (item.get("warehouse") or "").split(" - ")[0] }}</td>
      </tr>
    {%- endfor -%}
  </table></div>
  <div class="f remarks small">{{ (doc.get("terms") or "") | striptags }}</div>
  <div class="f tr total">{{ m(doc.get("total")) }}</div>
  <div class="f tr discount">{{ m(doc.get("discount_amount")) if doc.get("discount_amount") else "-" }}</div>
  <div class="f tr net">{{ m(doc.get("net_total")) }}</div>
  <div class="f tr vat">{{ m(doc.get("total_taxes_and_charges")) }}</div>
  <div class="f tr grand">{{ m(doc.get("rounded_total") or doc.get("grand_total")) }}</div>
  <div class="f amount-words">({{ number_to_thai_currency(doc.get("rounded_total") or doc.get("grand_total"), doc.get("currency")) }}).</div>
</div>
{%- endfor -%}
